import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, liveClaims } from '../claims/api';
import { gradeOn, listPeople, peopleKey } from '../people/api';
import { useCap, useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { claimDue, listRates, personDue, rateByGrade, ratesKey, splitDues, sumDues, trimmedSum } from './api';

/** The sheet's due-total: everyone's due-total added up, skipping those shown n/a, less the single
 *  highest and lowest when three or more have one. */
export function useDueTotal(sheetId: string, user: string): string {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const cap = useCap(sheetId, today);
  const charges = useLate(sheetId, today);
  const byGrade = rateByGrade(rates.data, today);
  const live = liveClaims(claims.data ?? [], people.data);
  const dues = (people.data ?? []).map((p) =>
    personDue(live.filter((c) => c.personId === p.id), rates.data, (d) => gradeOn(p, d), byGrade.get(p.grade), floor, charges, cap),
  );
  return trimmedSum(dues);
}

/** The sheet's settled-total and open-total: everyone's (see `splitDues`) simply added up, not trimmed. */
function useSplitTotals(sheetId: string, user: string) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const live = liveClaims(claims.data ?? [], people.data);
  const splits = (people.data ?? []).map((p) =>
    splitDues(live.filter((c) => c.personId === p.id), (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges)),
  );
  return { settled: sumDues(splits.map((s) => s.settled)), open: sumDues(splits.map((s) => s.open)) };
}

export function DueTotal({ sheetId, user }: { sheetId: string; user: string }) {
  const split = useSplitTotals(sheetId, user);
  return (
    <p>
      Due total <span data-testid="rollup-due-total">{useDueTotal(sheetId, user)}</span>{' '}
      settled <span data-testid="rollup-settled-total">{split.settled}</span>{' '}
      open <span data-testid="rollup-open-total">{split.open}</span>
    </p>
  );
}
import { useQuery } from '@tanstack/react-query';
import { postJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-MM-dd): every date decision and default uses it.
 *  `archived`: a steward archived it; everything stays visible and every change is refused. */
export type Sheet = { id: string; createdBy: string; today: string; archived: boolean };

/** Load a sheet by id; the server starts it empty the first time the id is used. */
export function openSheet(id: string, by: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/open?by=${encodeURIComponent(by)}`,
    {},
  );
}

/** Change the sheet's today; refused (rejects) when it is not a date. */
export function setSheetToday(id: string, by: string, today: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/today?by=${encodeURIComponent(by)}`,
    { today },
  );
}

/** Archive the sheet; refused (rejects) for anyone but a steward, and when already archived. */
export function archiveSheet(id: string, by: string): Promise<Sheet> {
  return postJson<Sheet>(
    `/api/sheets/${encodeURIComponent(id)}/archive?by=${encodeURIComponent(by)}`,
    {},
  );
}

/** Every query about a sheet lives under this key, so loading it again re-reads all of it. */
export const sheetKey = (id: string) => ['sheet', id] as const;

/** The loaded sheet's today, read from the sheet query `ActiveSheet` keeps; '' until loaded. */
export function useSheetToday(id: string, by: string): string {
  const sheet = useQuery({ queryKey: sheetKey(id), queryFn: () => openSheet(id, by) });
  return sheet.data?.today ?? '';
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { Header } from './Header';
import { Summary } from './Summary';

export const contributions = [
  SheetBody.fill({ order: -100, Component: Header }),
  SheetBody.fill({ order: 27, Component: Summary }),
];
import { useQuery } from '@tanstack/react-query';
import { SheetBody } from '../../slots/defs/sheetBody';
import { claimsKey, listClaims } from '../claims/api';
import { listPeople, peopleKey } from '../people/api';
import { useSheetId, useUser } from '../session/session';
import { openSheet, sheetKey } from './api';
import { SheetToday } from './SheetToday';
import { AsOf } from './AsOf';

/** The loaded sheet: its id, then everything kept on it (the sheet.body region). It shows once its
 *  people and claims are read too, so the sheet never shows without the rows it holds. */
export function ActiveSheet() {
  const [user] = useUser();
  const [sheetId] = useSheetId();
  const sheet = useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => openSheet(sheetId, user),
    enabled: sheetId !== '',
  });
  const people = useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => listPeople(sheetId),
    enabled: sheet.isSuccess,
  });
  const claims = useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => listClaims(sheetId),
    enabled: sheet.isSuccess,
  });

  if (sheetId === '') return <p data-testid="home-empty">No sheet loaded.</p>;
  if (sheet.isError) return <p data-testid="sheet-error">The sheet could not be loaded.</p>;
  if (!sheet.data || (!people.data && !people.isError) || (!claims.data && !claims.isError)) return <p data-testid="sheet-loading">Loading…</p>;

  return (
    <section>
      <h2>
        Sheet <span data-testid="sheet-current-id">{sheet.data.id}</span>
      </h2>
      <SheetToday key={sheet.data.id} sheet={sheet.data} user={user} />
      <AsOf />
      <SheetBody.Slot sheetId={sheet.data.id} user={user} />
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Late } from '../rates/api';
import { dueBy, type Claim } from '../claims/api';
import { gradeOn, listPeople, peopleKey } from '../people/api';

/** A value recorded for a sheet setting: its value as text ("" when blank), in force from its
 *  from-date (yyyy-MM-dd; null: from the beginning of time, and always for an undated key). A key
 *  may have several, one per from-date; a setting never set is not listed. */
export type Setting = { sheetId: string; key: string; value: string; from: string | null };
/** The role a user name has on the sheet; a name not listed is a clerk. */
export type Role = { sheetId: string; user: string; role: string };

/** The settings the screen offers: the clerk limit (two decimals; blank means no limit), the cap
 *  (two decimals; blank means none: the most a person's due-total can be), the pot (two decimals;
 *  blank means none; not dated: the sum a balanced pool's members cut between them), the
 *  floor (two decimals; the least a claim's live due can be) and the terms (whole days after its
 *  date by which a claim is due) and the late percent (two decimals; the share of an overdue claim's
 *  figure it gains for every full 30 days it is overdue) and the policy date (yyyy-MM-dd; blank means
 *  the sheet's today: a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering date (yyyy-MM-dd; blank means off: once the sheet's today is on or after it, a
 *  claim opened is numbered within its period, <period>-<n>, or X-<n> in no period). A grade's own terms
 *  (terms-<grade>; blank means the sheet's terms) fix the due-by of a claim added for a person of that
 *  grade on its date: its date plus those terms, kept when the terms or its date change later. The proof
 *  threshold (two decimals; blank means none): a claim whose due is above the one in force on its date
 *  cannot be settled or approved while it has no proofs. A grade's proof threshold (proof-threshold-<grade>,
 *  two decimals; blank means none): a claim whose person's grade in force on its date has one in force on
 *  that date goes by it instead of the sheet's. The note threshold (two decimals; blank means none):
 *  a claim whose due is above the one in force on its date cannot be opened with an empty note. The permission matrix (perm-<action>, a comma
 *  separated list of roles; blank means the standing rule, PERMISSION_STANDING): who may take each action.
 *  The entry date (yyyy-MM-dd; blank means off): while set, a new claim with a blank date (the claim form,
 *  the quick-add bar, a pasted line, a correction) takes it instead of the sheet's today.
 *  The grace days (whole days; blank means off): when the sheet's today changes, every open period whose
 *  to-date plus them is before the new today is closed. A grade's grace days (grace-<grade>, whole days;
 *  blank means none): a claim whose person's grade in force on its date has them in force on that date is
 *  overdue only once its due-by plus them is before the sheet's today, and its late charge's 30-day
 *  boundaries count from there; the due-by it shows is unchanged. The parent (a sheet id; blank means none;
 *  not dated): a grade with no rate in force on a date on this sheet takes its parent's, then its parent's
 *  parent's, up to three levels up; refused for the sheet itself, a sheet not loaded yet, or one below it. */
export const SETTING_KEYS = ['clerk-limit', 'cap', 'pot', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'policy-date',
  'period-numbering-from', 'entry-date', 'grace-days', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold', 'proof-threshold-A', 'proof-threshold-B', 'proof-threshold-C', 'note-threshold', 'perm-open', 'perm-settle', 'perm-void', 'perm-reassign', 'perm-close', 'perm-reopen', 'parent'] as const;

/** The roles that may take each action of the permission matrix while its entry is blank. */
export const PERMISSION_STANDING: Record<string, string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', close: 'clerk,steward',
  reassign: 'steward', reopen: 'steward',
};

/** A setting's value until it is first set. */
export const SETTING_DEFAULTS: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

/** The settings that are not dated: every other one is saved from a from-date (blank: the sheet's today). */
export const UNDATED_KEYS: readonly string[] = ['pot', 'policy-date', 'period-numbering-from', 'entry-date', 'grace-days', 'perm-open', 'perm-settle', 'perm-void',
  'perm-reassign', 'perm-close', 'perm-reopen', 'parent'];

/** A dated setting's value in force on a date (yyyy-MM-dd). */
export type DatedOn = (date: string) => string;

/** A setting's value in force on a date (yyyy-MM-dd): the one with the latest from-date on or before
 *  it; else its starting value (SETTING_DEFAULTS), and none (undefined) for a key with none. */
export function settingOn(settings: Setting[] | undefined, key: string, date: string): string | undefined {
  let found: Setting | undefined;
  for (const s of settings ?? []) {
    if (s.key !== key || (s.from !== null && s.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (s.from ?? '')) found = s;
  }
  return found === undefined ? SETTING_DEFAULTS[key] : found.value;
}

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export function listSettings(sheetId: string): Promise<Setting[]> {
  return getJson<Setting[]>(`${base(sheetId)}/settings`);
}

